] = $opt;                    $user_details = array("driver_id" => $userDetails->driver_id, "company_code" => $this->input->post('company_code'), "phone" => $this->input->post('phone'), "name" => $this->input->post('name'), "truck_number" => $this->input->post('truck_number'), "personal_pic" => base_url() . '/uploads/profile_img/original/' . $userDetails->personal_pic, "truck_pic" => base_url() . '/uploads/truck_img/original/' . $userDetails->truck_pic, "status" => '0');                    $this->response['userDetails'] = $user_details;                    $this->response['message'] = "Otp has been sent to your mobile number, please verify.";                    $this->response['status'] = 200;                } else {                    $this->response['message'] = 'user already exist.';                    $this->response['status'] = 400;                }            } else {                $_data = array(                    "company_code" => $this->input->post('company_code'),                    "phone" => $this->input->post('phone'),                    "name" => $this->input->post('name'),                    "truck_number" => $this->input->post('truck_number'),                    "status" => '0',                    "added_at" => date('Y-m-d H:i:s'),                    "updated_at" => date('Y-m-d H:i:s')                );                $extension = pathinfo($_FILES['personal_pic']['name'], PATHINFO_EXTENSION);                $personal_pic_filename = 'personal_pic_' . rand(10, 500) . time() . '.' . $extension;                $config = array(                    'upload_path' => "./uploads/profile_img/original/",                    'allowed_types' => "gif|jpg|png|jpeg",                    'overwrite' => TRUE,                    'file_name' => $personal_pic_filename,                );                $this->load->library('upload', $config);                $this->upload->initialize($config);                $this->upload->do_upload('personal_pic');                $extension1 = pathinfo($_FILES['truck_pic']['name'], PATHINFO_EXTENSION);                $truck_pic_filename = 'truck_pic_' . rand(10, 500) . time() . '.' . $extension1;                $config1 = array(                    'upload_path' => "./uploads/truck_img/original/",                    'allowed_types' => "gif|jpg|png|jpeg",                    'overwrite' => TRUE,                    'file_name' => $truck_pic_filename,                );                $this->load->library('upload', $config1);                $this->upload->initialize($config1);                $this->upload->do_upload('truck_pic');                if (isset($personal_pic_filename)) {                    $_data['personal_pic'] = $personal_pic_filename;                }                if (isset($truck_pic_filename)) {                    $_data['truck_pic'] = $truck_pic_filename;                }                $insert_id = $this->index_model->insertDriver($_data);                $opt = $this->send_otp($insert_id, $this->input->post('phone'));                $this->response['otp'] = $opt;                $userDetails = array("driver_id" => $insert_id, "company_code" => $this->input->post('company_code'), "phone" => $this->input->post('phone'), "name" => $this->input->post('name'), "truck_number" => $this->input->post('truck_number'), "personal_pic" => base_url() . '/uploads/profile_img/original/' . $personal_pic_filename, "truck_pic" => base_url() . '/uploads/truck_img/original/' . $truck_pic_filename, "status" => '0');                $this->response['userDetails'] = $userDetails;                $this->response['message'] = "Otp has been sent to your mobile number, please verify.";                $this->response['status'] = 200;            }        } else {            $error_msgs = $this->form_validation->error_array();            $this->response['message'] = $error_msgs;            $this->response['status'] = 400;        }        echo json_encode($this->response);        exit();    }    function login() {        $this->form_validation->set_rules('phone', 'phone ', 'trim|required|is_natural|xss_clean', array('required' => 'You must provide your %s.'));        if ($this->form_validation->run() == TRUE) {            $phone = $this->input->post('phone');            $userDetails = $this->index_model->get_active_phone_value($phone);            if (!empty($userDetails)) {                $opt = $this->send_otp($userDetails->driver_id, $phone);                $this->response['otp'] = $opt;                $this->response['userDetails'] = $userDetails;                $this->response['message'] = "Otp has been sent to your mobile number, please verify.";                $this->response['status'] = 200;            } else {                $this->response['message'] = 'Not registered.';                $this->response['status'] = 400;                   //redirect('admin/login');            }        } else {            $error_msgs = $this->form_validation->error_array();            $this->response['message'] = $error_msgs;            $this->response['status'] = 400;        }        echo json_encode($this->response);        exit();    }    function resend_otp() {        $this->form_validation->set_rules('phone', 'phone ', 'trim|required|is_natural|xss_clean', array('required' => 'You must provide your %s.'));        if ($this->form_validation->run() == TRUE) {            $phone = $this->input->post('phone');            $userDetails = $this->index_model->get_phone_value($phone);            if (!empty($userDetails)) {                $opt = $this->send_otp($userDetails->driver_id, $phone);                $this->response['otp'] = $opt;                $this->response['message'] = "Otp has been sent to your mobile number, please verify.";                $this->response['status'] = 200;            }        } else {            $error_msgs = $this->form_validation->error_array();            $this->response['message'] = $error_msgs;            $this->response['status'] = 400;        }        echo json_encode($this->response);        exit();    }    function otp_verification() {        $this->form_validation->set_rules('driver_id', 'driver id  ', 'trim|required|xss_clean', array('required' => 'You must provide your %s.'));        if ($this->form_validation->run() == TRUE) {            $_data = array(                "otp" => '',                "otp_verified" => '1',                "status" => '1',                "updated_at" => date('Y-m-d H:i:s')            );            $this->index_model->updateDriver($this->input->post('driver_id'), $_data);            $this->response['message'] = "Your account has been activated successfully.";            $this->response['status'] = 200;        } else {            $error_msgs = $this->form_validation->error_array();            $this->response['message'] = $error_msgs;            $this->response['status'] = 400;        }        echo json_encode($this->response);        exit();    }    function update_profile() {        $this->load->helper('file');        $this->form_validation->set_rules('driver_id', 'driver id  ', 'trim|required|xss_clean', array('required' => 'You must provide your %s.'));        $this->form_validation->set_rules('name', 'name ', 'trim|required|xss_clean', array('required' => 'You must provide your %s.'));        $this->form_validation->set_rules('phone', 'phone ', 'trim|required|is_natural|xss_clean', array('required' => 'You must provide your %s.'));        $this->form_validation->set_rules('truck_number', 'truck number ', 'trim|required|xss_clean', array('required' => 'You must provide your %s.'));        $this->form_validation->set_rules('company_code', 'company code ', 'trim|required|xss_clean', array('required' => 'You must provide your %s.'));        if ($this->form_validation->run() == TRUE) {            $phone = $this->input->post('phone');            $driver_id = $this->input->post('driver_id');            $userExistDetails = $this->index_model->phone_exist_except_self($driver_id, $phone);            //print_r($userDetails);exit;            if (empty($userExistDetails)) {                $userDetails = $this->index_model->get_user_value($driver_id);                $user_truck_pic_path = base_url() . 'uploads/truck_img/original/' . $userDetails->truck_pic;                $_data = array(                    "company_code" => $this->input->post('company_code'),                    "phone" => $this->input->post('phone'),                    "name" => $this->input->post('name'),                    "truck_number" => $this->input->post('truck_number'),                    "updated_at" => date('Y-m-d H:i:s')                );//echo $_FILES['truck_pic']['name'];exit;                if (isset($_FILES['truck_pic']['name']) && ($_FILES['truck_pic']['name'] != '')) {                    $allowed = array('png', 'jpg', 'gif', 'jpeg');                    $extension = pathinfo($_FILES['truck_pic']['name'], PATHINFO_EXTENSION);                    //exit;                    if (!in_array(strtolower($extension), $allowed)) {                        $error = 'Only the png,jpeg,jpg,gif type of file supported.';                    } else {                        $truck_pic_filename = 'truck_pic_' . rand(10, 500) . time() . '.' . $extension;                        $config = array(                            'upload_path' => "./uploads/truck_img/original/",                            'allowed_types' => "gif|jpg|png|jpeg",                            'overwrite' => TRUE,                            'file_name' => $truck_pic_filename,                        );                        $this->load->library('upload', $config);                        $this->upload->initialize($config);                        $this->upload->do_upload('truck_pic');                        //unset($config);                    }                }                if (empty($error)) {                    if (isset($truck_pic_filename)) {                        $_data['truck_pic'] = $truck_pic_filename;                        $user_truck_pic_path = base_url() . 'uploads/truck_img/original/' . $truck_pic_filename;                    }                    $this->index_model->updateDriver($driver_id, $_data);                    //$opt = $this->send_otp($driver_id, $phone);                    //$this->response['otp'] = $opt;                    $userDetails = array("driver_id" => $driver_id, "company_code" => $this->input->post('company_code'), "phone" => $this->input->post('phone'), "name" => $this->input->post('name'), "truck_number" => $this->input->post('truck_number'), "truck_pic" => $user_truck_pic_path);                    $this->response['userDetails'] = $userDetails;                    $this->response['message'] = "Your account has been updated successfully.";                    $this->response['status'] = 200;                } else {                    $this->response['message'] = $error;                    $this->response['status'] = 400;                }            } else {                $this->response['message'] = 'phone number already registered.';                $this->response['status'] = 400;            }        } else {            $error_msgs = $this->form_validation->error_array();            $this->response['message'] = $error_msgs;            $this->response['status'] = 400;        }        echo json_encode($this->response);        exit();    }    function update_profilepicture() {        $this->load->helper('file');        $this->form_validation->set_rules('driver_id', 'driver id  ', 'trim|required|xss_clean', array('required' => 'You must provide your %s.'));        if ($this->form_validation->run() == TRUE) {            $driver_id = $this->input->post('driver_id');            $extension = pathinfo($_FILES['personal_pic']['name'], PATHINFO_EXTENSION);            $personal_pic_filename = 'personal_pic_' . rand(10, 500) . time() . '.' . $extension;            $config = array(                'upload_path' => "./uploads/profile_img/original/",                'allowed_types' => "gif|jpg|png|jpeg",                'overwrite' => TRUE,                'file_name' => $personal_pic_filename,            );            $this->load->library('upload', $config);            $this->upload->initialize($config);            $this->upload->do_upload('personal_pic');            $_data = array(                "updated_at" => date('Y-m-d H:i:s')            );            if (isset($personal_pic_filename)) {                $_data['personal_pic'] = $personal_pic_filename;            }            $this->index_model->updateDriver($driver_id, $_data);            $userDetails = array("personal_pic" => base_url() . 'uploads/profile_img/original/' . $personal_pic_filename);            $this->response['userDetails'] = $userDetails;            $this->response['message'] = "Your profile picture updated successfully.";            $this->response['status'] = 200;        } else {            $error_msgs = $this->form_validation->error_array();            $this->response['message'] = $error_msgs;            $this->response['status'] = 400;        }        echo json_encode($this->response);        exit();    }    private function send_otp($user_id, $phone) {        $user_data['otp'] = rand(9000, 9999);        //send SMS        $postRequest = array(            'mobileNo' => $phone,            'otp' => $user_data['otp']        );        $cURLConnection = curl_init('https://api.flaplive.com/v1/feast-eat/generate-otp');        curl_setopt($cURLConnection, CURLOPT_POSTFIELDS, $postRequest);        curl_setopt($cURLConnection, CURLOPT_RETURNTRANSFER, true);        $apiResponse = curl_exec($cURLConnection);        curl_close($cURLConnection);        $user_data['updated_at'] = date('Y-m-d H:i:s');        $this->index_model->updateDriver($user_id, $user_data);        return $user_data['otp'];        exit();    }    function personal_pic_check($str) {        $allowed_mime_type_arr = array('image/jpeg', 'image/pjpeg', 'image/png', 'image/x-png');        $mime = get_mime_by_extension($_FILES['personal_pic']['name']);        if (isset($_FILES['personal_pic']['name']) && $_FILES['personal_pic']['name'] != "") {            if (in_array($mime, $allowed_mime_type_arr)) {                return true;            } else {                $this->form_validation->set_message('personal_pic_check', 'Please select only jpg/png file.');                return false;            }        } else {            $this->form_validation->set_message('personal_pic_check', 'Please choose a file to upload.');            return false;        }    }    function truck_pic_check($str) {        $allowed_mime_type_arr = array('image/jpeg', 'image/pjpeg', 'image/png', 'image/x-png');        $mime = get_mime_by_extension($_FILES['truck_pic']['name']);        if (isset($_FILES['truck_pic']['name']) && $_FILES['truck_pic']['name'] != "") {            if (in_array($mime, $allowed_mime_type_arr)) {                return true;            } else {                $this->form_validation->set_message('truck_pic_check', 'Please select only jpg/png file.');                return false;            }        } else {            $this->form_validation->set_message('truck_pic_check', 'Please choose a file to upload.');            return false;        }    }}